 impl PinnedCredentialMaterializer {
+    /// Observe the original resolution to completion, then re-enter the
+    /// current claim boundary before recording or publishing plaintext. A
+    /// receipt committed before later loss remains durable; it grants no
+    /// permission to hand out material after the recorder's awaited response.
+    async fn record_current_claimed_materialization(
+        realization: &AttemptCredentialRealization,
+        binding: &AttemptCredentialBinding,
+        context: &awaken_runtime_contract::RuntimeRunContext,
+    ) -> Result<(), String> {
+        let ownership = context
+            .ownership
+            .as_deref()
+            .ok_or_else(|| "credential-bearing materialization has no claim fence".to_owned())?;
+        awaken_runtime_contract::execution::verify_attempt_ownership(Some(ownership))
+            .await
+            .map_err(|error| error.to_string())?;
+        realization
+            .record(binding)
+            .await
+            .map_err(|error| error.to_string())?;
+        awaken_runtime_contract::execution::verify_attempt_ownership(Some(ownership))
+            .await
+            .map_err(|error| error.to_string())
+    }
+
     pub(super) fn claimed_provider_binding<'a>(
         candidate: &'a ResolvedModelCandidate,
         context: &'a awaken_runtime_contract::RuntimeRunContext,
@@ -131,10 +156,7 @@ impl PinnedCredentialMaterializer {
