-            .map_err(|error| error.to_string())?;
+        Self::record_current_claimed_materialization(realization, binding, context).await?;
         secret
             .into_secret()
             .map(Some)
@@ -168,10 +190,7 @@ impl PinnedCredentialMaterializer {
                 binding.selected_realization_kind,
             )
             .await?;
-        realization
-            .record(binding)
-            .await
-            .map_err(|error| error.to_string())?;
+        Self::record_current_claimed_materialization(realization, binding, context).await?;
         Ok(Some(secret))
